/// Every palette entry that names a model, in palette-id order.
#[must_use]
pub fn model_outputs() -> &'static [ModelOutputs] {
    ALL
}

/// One entry's declared outputs, or `None` for an entry with no model.
#[must_use]
pub fn outputs_for(unit_op: &str) -> Option<&'static ModelOutputs> {
    ALL.iter().find(|entry| entry.unit_op == unit_op)
}
